"""Build a derived observation contract; never overwrite the frozen parent."""
from pathlib import Path
import json,hashlib,copy
ROOT=Path(__file__).resolve().parents[1]
def digest(x):return hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 c=json.loads((ROOT/'dependencies/t06r3/data/case.json').read_text())
 r=next(x for x in json.loads((ROOT/'dependencies/t06r3/data/legacy_selection.json').read_text())['records'] if x['id']==c['recipe_id'])
 new=copy.deepcopy(c['measurement'])
 new.update(wavelength_um=['10'],weights=['1'],valid_band_um=['10','10'],instrument_id='synthetic_added_10um_discrete_operator')
 parent={'case_file_sha256':sha(ROOT/'dependencies/t06r3/data/case.json'),'full_bridge_payload_sha256':digest(c['bridge']),'bridge_contract_sha256':c['bridge']['bridge_contract_sha256'],'response_contract_sha256':c['bridge']['t04_response']['response_contract_sha256'],'measurement_contract_sha256':digest(c['measurement']),'material_contract_sha256':digest(c['material']),'recipe_payload_sha256':digest(r)}
 body={'stage':'T07R3','scope':'finite_encoded_synthetic_set_exclusion_only','inherited_case':c,'inherited_binding':parent,'recipe':r,'derived_observation_contract':{'version':'1','parent_measurement_sha256':parent['measurement_contract_sha256'],'channels':[{'id':'M0','role':'inherited','operator':c['measurement']},{'id':'M1','role':'new_separate_measurement','operator':new}],'extension':'M1 adds R at 10 um; M0 remains its original three-node weighted operator; no continuous-band claim','material_extension':{'parent_material_sha256':parent['material_contract_sha256'],'sample_state_id':c['material']['sample_state_id'],'nk_status':'same fixed synthetic constants explicitly postulated also at 10 um; real film nk unknown','domain_um':['4.25','4.26','4.27','10'],'temperature_K':300,'k':'0'},'same_specimen_between_channels':True,'latent_rule':'one z for all layers and both channels of the same specimen; each alternative hypothesis has its own existential z; different batches need separate z_b unless evidenced','error_joint_set':'Cartesian product of hard absolute bounds; independence is not asserted; safe outer superset for any dependence satisfying those margins','model_discrepancy':'exact_zero_by_synthetic_definition_only; real discrepancy unknown is unsupported','measurement_centers_R':['0.011583971','0.017070884'],'measurement_centers_origin':'rounded scalar synthetic M0/M1 at z=1 and all multipliers=1; not acquired data','error_abs_R':['0.001','0.001'],'error_is_not_coverage_probability':True},'parameterization':{'z':'h/h_ref from inherited positive source gate; dimensionless','d_i_um':'d_legacy_nm/1000 * z * multiplier_i; original substrate-to-incident numbering','not_time_dilation':True,'hypotheses':[{'id':'H0','description':'nominal layer multipliers','multipliers':['1']*6},{'id':'H_outer10','description':'original layer 6 (incident-most YF3 surrogate) 10 percent thicker','multipliers':['1']*5+['1.1']},{'id':'H_global002','description':'all layers multiplied by 1.002; product alias with z','multipliers':['1.002']*6}]},'tiny_budget':{'max_nodes_per_run':127,'min_width_z':'0.0004','candidate_count':3,'datasets':[['M0'],['M0','M1']],'devices':0,'monte_carlo_draws':0,'optimizer_calls':0},'physical_certification':False,'point12':'partial_unchanged','point2':'conditional_non_strict_unchanged','formal_review_chain':'pending'}
 body['derived_observation_contract_sha256']=digest(body['derived_observation_contract'])
 (ROOT/'data/case.json').write_text(json.dumps(body,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({'case_sha256':sha(ROOT/'data/case.json'),'derived_contract_sha256':body['derived_observation_contract_sha256'],'parent':parent},indent=2))
if __name__=='__main__':main()
